declare(strict_types=1);
require __DIR__.'/http060.php';
$published=request('action=draft-trash&id=1');checkHttp($published['status']===400,'Published project cannot be trashed');
$new=request('action=new-site');$created=request('action=new-site','super',['csrf'=>field($new['body'],'csrf'),'origin'=>'new','name'=>'Synthetic draft removal','slug'=>'trash-test-'.bin2hex(random_bytes(4)),'domain'=>'','primary'=>'#225cf0','accent'=>'#111827']);parse_str(location($created),$loc);$id=(int)($loc['id']??0);checkHttp($created['status']===303&&$id>1,'Synthetic draft created');
$confirm=request('action=draft-trash&id='.$id);checkHttp($confirm['status']===200&&str_contains($confirm['body'],'¿Seguro que quieres borrar este borrador?'),'GET shows named confirmation');checkHttp(request('action=site&id='.$id)['status']===200,'GET confirmation does not remove draft');
$post=['csrf'=>field($confirm['body'],'csrf'),'draft_token'=>field($confirm['body'],'draft_token')];checkHttp(request('action=draft-trash&id='.$id,'super',$post)['status']===400,'Server requires explicit confirmation');$post['confirm_draft']='1';$malformed=$post;$malformed['draft_token']=['invalid'];checkHttp(request('action=draft-trash&id='.$id,'super',$malformed)['status']===400,'Malformed confirmation token rejected');$invalid=$post;$invalid['draft_token']='stale';checkHttp(request('action=draft-trash&id='.$id,'super',$invalid)['status']===400,'Stale confirmation rejected');
foreach(['assigned','other'] as $role){$unauthorized=$post;$unauthorized['csrf']=field(request('action=dashboard',$role)['body'],'csrf');checkHttp(request('action=draft-trash&id='.$id,$role,$unauthorized)['status']===403,'Secondary administrator cannot trash project');}
$bad=$post;$bad['csrf']='bad';checkHttp(request('action=draft-trash&id='.$id,'super',$bad)['status']===419,'Trash requires CSRF');$removed=request('action=draft-trash&id='.$id,'super',$post);checkHttp($removed['status']===303,'Confirmed draft moves to trash');checkHttp(request('action=site&id='.$id)['status']===410,'Trashed project unavailable to edit');checkHttp(request('action=publish&id='.$id,'super',['csrf'=>$post['csrf']])['status']===410,'Trashed draft cannot be published');
$active=request('action=dashboard');$trash=request('action=dashboard&trash=1');checkHttp(!str_contains($active['body'],'Synthetic draft removal')&&str_contains($trash['body'],'Synthetic draft removal'),'Draft moved from active listing to trash');
$restore=request('action=draft-restore&id='.$id);checkHttp($restore['status']===200&&str_contains($restore['body'],'¿Restaurar este borrador?'),'Restore also asks for confirmation');checkHttp(request('action=site&id='.$id)['status']===410,'GET restore does not change state');$restorePost=['csrf'=>field($restore['body'],'csrf'),'draft_token'=>field($restore['body'],'draft_token'),'confirm_draft'=>'1'];checkHttp(request('action=draft-restore&id='.$id,'super',$restorePost)['status']===303,'Explicit restore returns draft');checkHttp(request('action=site&id='.$id)['status']===200,'Restored draft and pages remain available');checkHttp(request('action=draft-trash&id='.$id,'super',$post)['status']===303,'Draft can be trashed again without deleting content');
foreach(['trash-confirm.html'=>$confirm['body'],'trash-dashboard.html'=>$trash['body'],'restore-confirm.html'=>$restore['body']] as $name=>$body){$body=preg_replace('/(name="csrf" value=")[^"]*/','$1synthetic-csrf',$body);file_put_contents($fixture.'/'.$name,$body);}
echo "$count HTTP checks including draft trash PASS\n";
